CREATE TABLE ingest_batches(batch_id TEXT PRIMARY KEY,stream_key TEXT NOT NULL,revision INTEGER NOT NULL,metadata_hash TEXT NOT NULL,payload_json TEXT NOT NULL,page_count INTEGER NOT NULL,total_items INTEGER,status TEXT NOT NULL DEFAULT 'receiving',created_at TEXT NOT NULL,UNIQUE(stream_key,revision));
CREATE TABLE ingest_pages(idempotency_key TEXT PRIMARY KEY,batch_id TEXT NOT NULL,page_no INTEGER NOT NULL,payload_hash TEXT NOT NULL,receipt_json TEXT NOT NULL,r2_key TEXT NOT NULL,UNIQUE(batch_id,page_no));
CREATE TABLE batch_items(batch_id TEXT NOT NULL,topic_id TEXT NOT NULL,item_id TEXT NOT NULL,payload_json TEXT NOT NULL,PRIMARY KEY(batch_id,topic_id));
CREATE TABLE content_items(id TEXT PRIMARY KEY,market TEXT,region_code TEXT NOT NULL,source_system TEXT NOT NULL,run_date TEXT NOT NULL,selection_scope TEXT NOT NULL DEFAULT 'candidate_topics',topic_key TEXT NOT NULL,title TEXT NOT NULL,summary TEXT,url TEXT NOT NULL,source TEXT NOT NULL,heat REAL,ai_rank INTEGER,ai_reason TEXT,topic TEXT,relevance TEXT,status TEXT NOT NULL DEFAULT 'candidate' CHECK(status IN ('candidate','selected','published','failed','legacy_hot')),reviewed_by TEXT,reviewed_at TEXT,queued_at TEXT,published_at TEXT,publish_result TEXT,category TEXT,opportunity_score REAL,engagement_total TEXT,lead_created_at TEXT,article_path TEXT,revision INTEGER NOT NULL,payload_json TEXT NOT NULL,available INTEGER NOT NULL DEFAULT 0,UNIQUE(source_system,run_date,region_code,selection_scope,topic_key));
CREATE INDEX items_region_date ON content_items(run_date,region_code,status,available);
CREATE TABLE content_versions(item_id TEXT NOT NULL,revision INTEGER NOT NULL,payload_json TEXT NOT NULL,batch_id TEXT NOT NULL,PRIMARY KEY(item_id,revision));
CREATE TABLE region_reviews(run_date TEXT NOT NULL,region_code TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',locked INTEGER NOT NULL DEFAULT 0,reviewed_by TEXT,updated_at TEXT NOT NULL,PRIMARY KEY(run_date,region_code));
CREATE TABLE review_picks(item_id TEXT PRIMARY KEY,run_date TEXT NOT NULL,region_code TEXT NOT NULL,reviewed_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE review_ai_runs(id TEXT PRIMARY KEY,run_date TEXT NOT NULL,region_code TEXT NOT NULL,status TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT,result_json TEXT);
CREATE TABLE review_ai_calls(id TEXT PRIMARY KEY,run_id TEXT NOT NULL,kind TEXT NOT NULL,region_code TEXT,model TEXT,created_at TEXT NOT NULL,prompt_tokens INTEGER,completion_tokens INTEGER,cache_hit_tokens INTEGER,estimated_cost_usd REAL,pricing_json TEXT,usage_json TEXT,error_code TEXT);
CREATE TABLE submission_jobs(id TEXT PRIMARY KEY,item_id TEXT NOT NULL UNIQUE,external_id TEXT NOT NULL UNIQUE,run_date TEXT NOT NULL,reviewed_by TEXT NOT NULL,state TEXT NOT NULL,snapshot_json TEXT NOT NULL,article_key TEXT,payload_key TEXT,hub_id TEXT,error TEXT,attempts INTEGER NOT NULL DEFAULT 0,dry_run INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE task_outbox(id TEXT PRIMARY KEY,kind TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL);
CREATE TABLE rate_limits(ip_hash TEXT NOT NULL,minute INTEGER NOT NULL,count INTEGER NOT NULL,PRIMARY KEY(ip_hash,minute));
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE audit_events(id TEXT PRIMARY KEY,action TEXT NOT NULL,reviewed_by TEXT,payload_json TEXT,created_at TEXT NOT NULL);
